(()=>{const section=document.querySelector('#nutrition'),controls=document.createElement('div');controls.className='fuel-history-controls';controls.innerHTML='<button type="button" class="secondary" id="fuelPrevious" aria-label="Previous day">←</button><label>Daily Fuel date<input id="fuelDate" type="date" value="'+fuelDay+'"></label><button type="button" class="secondary" id="fuelNext" aria-label="Next day">→</button><button type="button" class="text-button" id="fuelToday">Today</button>';section.querySelector('.section-heading').after(controls);const list=document.createElement('section');list.className='fuel-meal-history';list.innerHTML='<h3>Meals for this day</h3><p class="tiny">Edit an entry to correct its nutrition, time or date. Targets shown are historical when available; otherwise current targets are used.</p><div id="fuelMealList"></div>';section.append(list);function choose(date){if(!date)return;fuelDay=date;document.querySelector('#fuelDate').value=date;document.querySelector('#journalDate').value=date;renderNutrition();renderJournal();render();document.dispatchEvent(new Event('fuel:date'));}window.chooseFuelDay=choose;function step(n){const d=CalendarCore.parse(fuelDay);d.setDate(d.getDate()+n);choose(CalendarCore.dayKey(d));}controls.querySelector('#fuelPrevious').onclick=()=>step(-1);controls.querySelector('#fuelNext').onclick=()=>step(1);controls.querySelector('#fuelToday').onclick=()=>choose(dateKey());controls.querySelector('#fuelDate').onchange=e=>choose(e.target.value);function render(){const meals=state.meals.filter(m=>m.date===fuelDay).sort((a,b)=>a.time.localeCompare(b.time));document.querySelector('#fuelMealList').innerHTML=meals.length?meals.map(m=>'<div class="fuel-meal-row"><div><strong>'+safe(m.name)+'</strong><p>'+safe(m.time)+' · '+number(m.calories)+' kcal · '+number(m.protein)+' g protein · '+number(m.carbs)+' g carbs · '+(m.fat==null?'fat not recorded':number(m.fat)+' g fat')+'</p></div><button type="button" class="secondary" data-edit="'+safe(m.id)+'">Edit</button><button type="button" class="text-button" data-delete="'+safe(m.id)+'">Remove</button></div>').join(''):'<p>No meals recorded on this day.</p>';list.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const m=state.meals.find(x=>x.id===b.dataset.edit);openMeal();editingMealId=m.id;for(const k of ['name','date','time','calories','protein','carbs','fat'])document.querySelector('#mealForm').elements[k].value=m[k]??'';mealPhoto=m.photo||'';ingredients=m.ingredients||[];if(mealPhoto){document.querySelector('#mealPreview').src=mealPhoto;document.querySelector('#mealPreview').hidden=false;}});list.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const prev=state.meals.slice();state.meals=state.meals.filter(m=>m.id!==b.dataset.delete);if(!save())state.meals=prev;renderNutrition();renderJournal();render();});}const original=renderJournal;renderJournal=function(){original();render();};document.addEventListener('meals:render',render);document.addEventListener('fuel:changed',render);render();})();